<?php foreach($cards as $card):$fields=json_decode($card['fields_json'],true);?><article class="cms-card"><?php if($card['media_token']):$width=(int)$card['media_width'];$srcset=[];foreach([320,640,1280] as $w)if($w<$width)$srcset[]='/media?token='.$card['media_token'].'&width='.$w.' '.$w.'w';$srcset[]='/media?token='.$card['media_token'].' '.$width.'w';?><img src="/media?token=<?= e($card['media_token']) ?>" srcset="<?= e(implode(', ',$srcset)) ?>" sizes="(max-width: 640px) 100vw, (max-width: 1024px) 50vw, 33vw" width="<?= e($width) ?>" height="<?= e($card['media_height']) ?>" alt="<?= e($card['media_alt']) ?>" loading="lazy"><?php endif?><div><h3><?= e($card['title']) ?></h3><?php if($kind==='events'):?><p><time datetime="<?= e($fields['event_date']) ?>"><?= e($fields['event_date']) ?></time> · <?= e($fields['location']) ?></p><?php endif?><?php if($kind==='reviews'):?><p><?= e($fields['author']) ?> · <?= e($fields['rating']) ?>/5</p><?php endif?><p class="cms-prose"><?= e($card['body']) ?></p><?php if($fields['link']??''):?><a href="<?= e($fields['link']) ?>"><?= e(($fields['link_label']??'')?:'Ver información') ?></a><?php endif?></div></article><?php endforeach?>
